import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`study-help`,heroTitle:`A study system that grows with you`,heroSubtitle:`Perplexity Computer builds step-by-step explanations, adaptive quizzes, and flashcards from your topics — automatically.`,inputUrlCta:`Build my study plan`,inputUrlPlaceholder:`e.g. topic, class, or exam`,inputUrlPrefill:`Help me study {url}. (1) Identify the core concepts, prerequisite knowledge, and likely trouble spots. (2) Build step-by-step explanations that start simple and add complexity gradually. (3) Generate adaptive quizzes and guided questions that adjust to my level. (4) Create flashcards and a study plan with spaced-repetition review sessions. (5) Pull in scholarly or high-quality sources when needed and cite them in the explanation set. Deliver a complete study session with explanations, quizzes, flashcards, and next steps.`,heroOverlaySteps:[`Analyzing your topic and identifying core concepts to cover`,`Building step-by-step explanations with scholarly sources`,`Generating adaptive quizzes and flashcards matched to your level`,`Personalized study plan with explanations, quizzes, and flashcards — ready to learn`],generatingSteps:[`Identifying the subject area, key concepts, and prerequisite knowledge`,`Designing an agent to research scholarly sources and build layered explanations`,`Configuring adaptive quizzes, guided questions, and flashcard generation`,`Setting up personalized difficulty scaling and progress tracking`],featureSectionTitle:`From question to deep understanding`,featureCardTitles:[`Connects to your study stack`,`Outputs you can study from`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Notion, Google Sheets, Airtable — Computer plugs into your tools so notes, flashcards, and study plans stay organized in one place.`,`Step-by-step concept breakdowns. Adaptive mini-quizzes. Flashcard decks. Source-backed explanations with cross-referenced academic citations.`],capabilitySectionTitle:`Your personal tutor, on autopilot`,capabilitySectionSubtitle:`Ask a question, step away, come back to a complete study session.`,capabilityCards:[{title:`Active Learning`,description:`Computer can turn any topic into step-by-step explanations with guided questions that test understanding — not just regurgitate answers.`},{title:`Adaptive Quizzes`,description:`Computer can generate mini-quizzes calibrated to your level — adjusting difficulty based on how you answer and what you've struggled with before.`},{title:`Deep Research`,description:`Computer can read full pages, prioritize scholarly sources, cross-reference claims, and surface disagreements — not just pull summaries.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Notion, Google Sheets, and Google Drive — so flashcards, notes, and study plans live where you already work.`},{title:`Remembers Your Level`,description:`Computer can remember your past questions, quiz results, and weak areas across sessions — so every study session picks up where you left off.`},{title:`Review Reminders`,description:`Computer can schedule spaced-repetition reviews and alert you when it's time to revisit concepts before they fade from memory.`}]});export{t as default};
